function sortedSquares(nums) {
  const n = nums.length, out = new Array(n);
  let lo = 0, hi = n - 1;
  for (let write = n - 1; write >= 0; write--) {
    const a = nums[lo] * nums[lo], b = nums[hi] * nums[hi];
    if (a > b) {
      out[write] = a;
      lo++;
    } else {
      out[write] = b;
      hi--;
    }
  }
  return out;
}
